".footer {
  min-height: 320px;
  background: var(--black);
  padding: 80px 0 40px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  color: var(--white);
}

.footer .container {
  width: 100%;
  max-width: 1200px;
  padding: 0 var(--side-gap);
  display: flex;
  flex-direction: column;
  gap: 48px;
}

.footer-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 32px;
}

.footer-logo {
  color: var(--primary);
  font-size: 28px;
}

.footer-links {
  display: flex;
  gap: 24px;
}

.footer-link {
  color: var(--white);
  text-decoration: none;
  font-size: 16px;
  transition: color 0.2s ease;
}

.footer-link:hover {
  color: var(--primary);
}

.copyright {
  color: var(--gray-mid);
  font-size: 14px;
  text-align: center;
  border-top: 1px solid #333;
  padding-top: 24px;
}"

